namespace sv_994307d451dd4f13bd39c816d3fdbeae;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

namespace sv_994307d451dd4f13bd39c816d3fdbeae;

public class ApplicationService : IApplicationService
{
    public async Task<int> SubmitApplicationAsync(JobApplication application)
    {
        await Task.Delay(1000);
        return Random.Shared.Next(10000, 99999);
    }

    public async Task<bool> ValidateEmailAsync(string email)
    {
        await Task.Delay(300);
        return !string.IsNullOrWhiteSpace(email)
            && email.Contains('@')
            && email.Contains('.');
    }
}

@using System.ComponentModel.DataAnnotations

<fieldset class="work-entry">
    <legend>Position @(Index + 1)</legend>

    @if (ShowRemove)
    {
        <button type="button" class="btn btn-remove" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
    }

    <div class="form-row">
        <div class="form-group">
            <label for="company-@Index">Company Name *</label>
            <input id="company-@Index" type="text" @bind="Entry.Company" @bind:event="oninput" required />
        </div>
        <div class="form-group">
            <label for="title-@Index">Job Title *</label>
            <input id="title-@Index" type="text" @bind="Entry.Title" @bind:event="oninput" required />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label for="start-@Index">Start Date *</label>
            <input id="start-@Index" type="date" @bind="Entry.StartDate" required />
        </div>
        <div class="form-group">
            <label for="end-@Index">End Date</label>
            <input id="end-@Index" type="date" @bind="Entry.EndDate" disabled="@Entry.IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" @bind="Entry.IsCurrent" @bind:after="OnCurrentChanged" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label for="desc-@Index">Description</label>
        <textarea id="desc-@Index" rows="3" @bind="Entry.Description" @bind:event="oninput"></textarea>
    </div>
</fieldset>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private void OnCurrentChanged()
    {
        if (Entry.IsCurrent)
        {
            Entry.EndDate = null;
        }
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime? StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";

        public bool IsValid =>
            !string.IsNullOrWhiteSpace(Company)
            && !string.IsNullOrWhiteSpace(Title)
            && StartDate.HasValue;
    }
}

