{"path": "/tmp/sv-994307d451dd4f13bd39c816d3fdbeae/Components/Pages/Apply/StepIndicator.razor", "file_text": "<nav class="step-indicator" aria-label="Application steps">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var step = i;
        var isCompleted = step < CurrentStep;
        var isCurrent = step == CurrentStep;
        var isFuture = step > CurrentStep;

        <button class="step @(isCurrent ? "step--current" : "") @(isCompleted ? "step--completed" : "") @(isFuture ? "step--future" : "")"
                disabled="@isFuture"
                @onclick="() => OnStepClicked.InvokeAsync(step)">
            <span class="step__number">
                @if (isCompleted)
                {
                    <span aria-hidden="true">✓</span>
                }
                else
                {
                    @(step + 1)
                }
            </span>
            <span class="step__label">@StepNames[step]</span>
        </button>

        @if (step < StepNames.Count - 1)
        {
            <span class="step__connector @(step < CurrentStep ? "step__connector--completed" : "")"></span>
        }
    }
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly List<string> StepNames =
    [
        "Personal Info",
        "Work History",
        "References",
        "Cover Letter",
        "Review & Submit"
    ];
}
"}

