@using static WorkEntryForm

<section>
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="Entries[index]"
                       Index="index"
                       ShowRemove="Entries.Count > 1"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn btn-secondary" @onclick="AddEntry">
        + Add Another Position
    </button>

    @if (!string.IsNullOrEmpty(validationMessage))
    {
        <p class="validation-error">@validationMessage</p>
    }

    <div class="step-buttons">
        <button type="button" class="btn" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</section>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? validationMessage;

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        validationMessage = null;

        if (!Entries.All(e => e.IsValid))
        {
            validationMessage = "Please fill in company, title, and start date for all positions.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}

@using static ReferenceForm

<section>
    <h2>References</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <ReferenceForm Entry="Entries[index]"
                       Index="index"
                       ShowRemove="Entries.Count > 2"
                       OnRemove="() => RemoveEntry(index)" />
    }

    @if (Entries.Count < 3)
    {
        <button type="button" class="btn btn-secondary" @onclick="AddEntry">
            + Add Reference
        </button>
    }

    @if (!string.IsNullOrEmpty(validationMessage))
    {
        <p class="validation-error">@validationMessage</p>
    }

    <div class="step-buttons">
        <button type="button" class="btn" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</section>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> Entries { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? validationMessage;

    private void AddEntry()
    {
        if (Entries.Count < 3)
        {
            Entries.Add(new ReferenceModel());
        }
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 2)
        {
            Entries.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        validationMessage = null;

        if (!Entries.All(e => e.IsValid))
        {
            validationMessage = "Please fill in name, relationship, and email for all references.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}

@using static PersonalInfoStep
@using static WorkEntryForm
@using static ReferenceForm

<section class="review-step">
    <h2>Review & Submit</h2>

    @if (IsSubmitted)
    {
        <div class="confirmation">
            <h3>🎉 Application Submitted!</h3>
            <p>Your application has been received. Your confirmation number is:</p>
            <p class="application-id">@ApplicationId</p>
        </div>
    }
    else
    {
        <div class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button type="button" class="btn-link" @onclick='() => OnEdit.InvokeAsync(0)'>Edit</button>
            </div>
            <dl>
                <dt>Full Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button type="button" class="btn-link" @onclick='() => OnEdit.InvokeAsync(1)'>Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-card">
                    <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                    <br />
                    <span>@entry.StartDate?.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button type="button" class="btn-link" @onclick='() => OnEdit.InvokeAsync(2)'>Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-card">
                    <strong>@r.Name</strong> — @r.Relationship
                    <br />
                    @r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $" | {r.Phone}" : "")
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button type="button" class="btn-link" @onclick='() => OnEdit.InvokeAsync(3)'>Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </div>

        @if (!string.IsNullOrEmpty(errorMessage))
        {
            <p class="validation-error">@errorMessage</p>
        }

        <div class="step-buttons">
            <button type="button" class="btn" @onclick="OnBack" disabled="@isSubmitting">Back</button>
            <button type="button" class="btn btn-primary" @onclick="HandleSubmit" disabled="@isSubmitting">
                @(isSubmitting ? "Submitting…" : "Submit Application")
            </button>
        </div>
    }
</section>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<int> OnEdit { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public EventCallback OnSubmit { get; set; }

    [Parameter] public bool IsSubmitted { get; set; }
    [Parameter] public int ApplicationId { get; set; }

    private bool isSubmitting;
    private string? errorMessage;

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        errorMessage = null;
        try
        {
            await OnSubmit.InvokeAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

