{"file_text": "<section>
    <h2>Personal Information</h2>

    <div class="form-group">
        <label for="fullname">Full Name *</label>
        <input id="fullname" type="text" @bind="Model.FullName" @bind:event="oninput" required />
    </div>

    <div class="form-group">
        <label for="email">Email Address *</label>
        <input id="email" type="email" @bind="Model.Email" @bind:event="oninput" required />
        @if (!string.IsNullOrEmpty(emailError))
        {
            <span class="field-error">@emailError</span>
        }
    </div>

    <div class="form-group">
        <label for="phone">Phone Number *</label>
        <input id="phone" type="tel" @bind="Model.Phone" @bind:event="oninput" required />
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <textarea id="address" rows="2" @bind="Model.Address" @bind:event="oninput" required></textarea>
    </div>

    @if (!string.IsNullOrEmpty(validationMessage))
    {
        <p class="validation-error">@validationMessage</p>
    }

    <div class="step-buttons">
        <button type="button" class="btn btn-primary" @onclick="HandleNext" disabled="@isValidating">
            @(isValidating ? "Validating…" : "Next")
        </button>
    </div>
</section>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;

    private string? validationMessage;
    private string? emailError;
    private bool isValidating;

    private async Task HandleNext()
    {
        validationMessage = null;
        emailError = null;

        if (string.IsNullOrWhiteSpace(Model.FullName)
            || string.IsNullOrWhiteSpace(Model.Email)
            || string.IsNullOrWhiteSpace(Model.Phone)
            || string.IsNullOrWhiteSpace(Model.Address))
        {
            validationMessage = "Please fill in all required fields.";
            return;
        }

        isValidating = true;
        try
        {
            var isEmailValid = await ApplicationService.ValidateEmailAsync(Model.Email);
            if (!isEmailValid)
            {
                emailError = "Please enter a valid email address.";
                return;
            }

            await OnNext.InvokeAsync();
        }
        finally
        {
            isValidating = false;
        }
    }

