@page "/apply"
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

@using static PersonalInfoStep
@using static WorkEntryForm
@using static ReferenceForm

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep" OnStepClicked="GoToStep" />

    <div class="step-content">
        @switch (currentStep)
        {
            case 0:
                <PersonalInfoStep Model="personalInfo"
                                  ApplicationService="ApplicationService"
                                  OnNext="NextStep" />
                break;

            case 1:
                <WorkHistoryStep Entries="workEntries"
                                 OnNext="NextStep"
                                 OnBack="PreviousStep" />
                break;

            case 2:
                <ReferencesStep Entries="references"
                                OnNext="NextStep"
                                OnBack="PreviousStep" />
                break;

            case 3:
                <CoverLetterStep @bind-CoverLetterText="coverLetter"
                                 OnNext="NextStep"
                                 OnBack="PreviousStep" />
                break;

            case 4:
                <ReviewStep Personal="personalInfo"
                            WorkEntries="workEntries"
                            References="references"
                            CoverLetter="coverLetter"
                            OnEdit="GoToStep"
                            OnBack="PreviousStep"
                            OnSubmit="SubmitApplication"
                            IsSubmitted="isSubmitted"
                            ApplicationId="applicationId" />
                break;
        }
    </div>
</div>

@code {
    private int currentStep;
    private bool isSubmitted;
    private int applicationId;

    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = [new()];
    private List<ReferenceModel> references = [new(), new()];
    private string coverLetter = "";

    private void NextStep() => currentStep++;
    private void PreviousStep() => currentStep--;

    private void GoToStep(int step)
    {
        if (step < currentStep)
        {
            currentStep = step;
        }
    }

    private async Task SubmitApplication()
