    align-items: center;
    justify-content: center;
    gap: 0;
    flex-wrap: wrap;
}

::deep .step {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.25rem;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0.5rem;
    min-width: 5.5rem;
}

::deep .step:disabled {
    cursor: default;
}

::deep .step__number {
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.875rem;
    border: 2px solid #ccc;
    color: #999;
    background: #fff;
    transition: all 0.2s;
}

::deep .step--current .step__number {
    border-color: #4f46e5;
    background: #4f46e5;
    color: #fff;
}

::deep .step--completed .step__number {
    border-color: #22c55e;
    background: #22c55e;
    color: #fff;
}

::deep .step__label {
    font-size: 0.75rem;
    color: #666;
    text-align: center;
    white-space: nowrap;
}

::deep .step--current .step__label {
    color: #4f46e5;
    font-weight: 600;
}

::deep .step--completed .step__label {
    color: #22c55e;
}

::deep .step__connector {
    width: 2.5rem;
    height: 2px;
    background: #ccc;
    align-self: center;
    margin-bottom: 1.25rem;
}

::deep .step__connector--completed {
    background: #22c55e;
}

/* ── Forms ── */
::deep .form-group {
    margin-bottom: 1rem;
