+/* ── Layout ── */
+.apply-page {
+    max-width: 800px;
+    margin: 0 auto;
+    padding: 2rem 1rem;
+}
+
+.apply-page h1 {
+    text-align: center;
+    margin-bottom: 2rem;
+}
+
+.step-content {
+    margin-top: 2rem;
+}
+
+/* ── Step Indicator ── */
+::deep .step-indicator {
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    gap: 0;
+    flex-wrap: wrap;
+}
+
+::deep .step {
+    display: flex;
+    flex-direction: column;
+    align-items: center;
+    gap: 0.25rem;
+    background: none;
+    border: none;
+    cursor: pointer;
+    padding: 0.5rem;
+    min-width: 5.5rem;
+}
+
+::deep .step:disabled {
+    cursor: default;
+}
+
+::deep .step__number {
+    width: 2rem;
+    height: 2rem;
+    border-radius: 50%;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    font-weight: bold;
+    font-size: 0.875rem;
+    border: 2px solid #ccc;
+    color: #999;
+    background: #fff;
+    transition: all 0.2s;
+}
+
+::deep .step--current .step__number {
+    border-color: #4f46e5;
+    background: #4f46e5;
+    color: #fff;
+}
+
+::deep .step--completed .step__number {
+    border-color: #22c55e;
+    background: #22c55e;
+    color: #fff;
+}
+
+::deep .step__label {
+    font-size: 0.75rem;
+    color: #666;
+    text-align: center;
+    white-space: nowrap;
+}
+
+::deep .step--current .step__label {
+    color: #4f46e5;
+    font-weight: 600;
+}
+
+::deep .step--completed .step__label {
+    color: #22c55e;
+}
+
+::deep .step__connector {
+    width: 2.5rem;
+    height: 2px;
+    background: #ccc;
+    align-self: center;
+    margin-bottom: 1.25rem;
+}
+
+::deep .step__connector--completed {
+    background: #22c55e;
+}
+
+/* ── Forms ── */
+::deep .form-group {
+    margin-bottom: 1rem;
+}
+
+::deep .form-group label {
+    display: block;
+    margin-bottom: 0.25rem;
+    font-weight: 500;
+    font-size: 0.875rem;
+}
+
+::deep .form-group input[type="text"],
+::deep .form-group input[type="email"],
+::deep .form-group input[type="tel"],
+::deep .form-group input[type="date"],
+::deep .form-group textarea {
+    width: 100%;
+    padding: 0.5rem 0.75rem;
+    border: 1px solid #d1d5db;
+    border-radius: 0.375rem;
+    font-size: 0.875rem;
+    box-sizing: border-box;
+}
+
+::deep .form-group input:focus,
+::deep .form-group textarea:focus {
+    outline: none;
+    border-color: #4f46e5;
+    box-shadow: 0 0 0 2px rgba(79, 70, 229, 0.2);
+}
+
+::deep .form-group input:disabled {
+    background: #f3f4f6;
+    color: #9ca3af;
+}
+
+::deep .form-row {
+    display: grid;
+    grid-template-columns: 1fr 1fr;
+    gap: 1rem;
+}
+
+::deep .checkbox-label {
+    display: inline-flex !important;
+    align-items: center;
+    gap: 0.5rem;
+    font-weight: normal !important;
+    margin-top: 0.25rem;
+    cursor: pointer;
+}
+
+::deep .checkbox-label input[type="checkbox"] {
+    width: auto;
+}
+
+/* ── Fieldsets ── */
+::deep fieldset {
+    border: 1px solid #e5e7eb;
+    border-radius: 0.5rem;
+    padding: 1rem 1.25rem;
+    margin-bottom: 1rem;
+    position: relative;
+}
+
+::deep fieldset legend {
+    font-weight: 600;
+    padding: 0 0.5rem;
+    font-size: 0.875rem;
+}
+
+/* ── Buttons ── */
+::deep .step-buttons {
+    display: flex;
+    justify-content: space-between;
+    margin-top: 1.5rem;
+    padding-top: 1rem;
+    border-top: 1px solid #e5e7eb;
+}
+
+::deep .btn {
+    padding: 0.5rem 1.25rem;
+    border-radius: 0.375rem;
+    font-size: 0.875rem;
+    border: 1px solid #d1d5db;
+    background: #fff;
+    cursor: pointer;
+    font-weight: 500;
+}
+
+::deep .btn:hover {
+    background: #f9fafb;
+}
+
+::deep .btn:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+::deep .btn-primary {
+    background: #4f46e5;
+    color: #fff;
+    border-color: #4f46e5;
+}
+
+::deep .btn-primary:hover {
+    background: #4338ca;
+}
+
+::deep .btn-secondary {
+    background: #f3f4f6;
+    border-color: #d1d5db;
+}
+
+::deep .btn-remove {
+    position: absolute;
+    top: -0.5rem;
+    right: 0.5rem;
+    background: #fee2e2;
+    color: #dc2626;
+    border-color: #fca5a5;
+    padding: 0.125rem 0.5rem;
+    font-size: 0.75rem;
+}
+
+::deep .btn-remove:hover {
+    background: #fca5a5;
+}
+
+::deep .btn-link {
+    background: none;
+    border: none;
+    color: #4f46e5;
+    cursor: pointer;
+    font-size: 0.875rem;
+    text-decoration: underline;
+    padding: 0;
+}
+
+::deep .btn-link:hover {
+    color: #4338ca;
+}
+
+/* ── Validation ── */
+::deep .validation-error {
+    color: #dc2626;
+    font-size: 0.875rem;
+    margin-top: 0.5rem;
+}
+
+::deep .field-error {
+    color: #dc2626;
+    font-size: 0.8125rem;
+    display: block;
+    margin-top: 0.25rem;
+}
+
+/* ── Cover Letter ── */
+::deep .char-count {
+    font-size: 0.8125rem;
+    color: #6b7280;
+    text-align: right;
+    display: block;
+    margin-top: 0.25rem;
+}
+
+::deep .char-count--limit {
+    color: #dc2626;
+    font-weight: 600;
+}
+
+/* ── Review Step ── */
+::deep .review-section {
+    border: 1px solid #e5e7eb;
+    border-radius: 0.5rem;
+    padding: 1rem 1.25rem;
+    margin-bottom: 1rem;
+}
+
+::deep .review-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 0.75rem;
+}
+
+::deep .review-header h3 {
+    margin: 0;
+    font-size: 1rem;
+}
+
+::deep .review-section dl {
+    display: grid;
+    grid-template-columns: 8rem 1fr;
+    gap: 0.25rem 1rem;
+    margin: 0;
+    font-size: 0.875rem;
+}
+
+::deep .review-section dt {
+    font-weight: 600;
+    color: #6b7280;
+}
+
+::deep .review-card {
+    padding: 0.5rem 0;
+    font-size: 0.875rem;
+    border-bottom: 1px solid #f3f4f6;
+}
+
+::deep .review-card:last-child {
+    border-bottom: none;
+}
+
+::deep .cover-letter-preview {
+    font-size: 0.875rem;
+    white-space: pre-wrap;
+    background: #f9fafb;
+    padding: 0.75rem;
+    border-radius: 0.375rem;
+}
+
+/* ── Confirmation ── */
+::deep .confirmation {
+    text-align: center;
+    padding: 2rem;
+}
+
+::deep .confirmation h3 {
+    font-size: 1.5rem;
+    margin-bottom: 0.5rem;
+}
+
+::deep .application-id {
+    font-size: 2rem;
+    font-weight: bold;
+    color: #4f46e5;
+    font-family: monospace;
+}
+

